// "Is this copy ready?" Borrows a connection from the pool, the way a payment does.
fun ready(pool: DataSource): Boolean =
    try {
        pool.connection.use { c -> c.isValid(1) }      // waits for a free connection, then asks the database
    } catch (e: SQLException) {
        false
    }

