class FixedTimeoutDetector(val timeoutMs: Long) : FailureDetector {
    private var last: Long? = null
    override fun heartbeat(atMs: Long) { last = atMs }
    override fun suspects(nowMs: Long) = last?.let { nowMs - it > timeoutMs } ?: false
}

override fun heartbeat(atMs: Long) {
    last?.let { previous ->
        val gap = atMs - previous
        gaps.addLast(gap); sum += gap; sumOfSquares += gap.toDouble() * gap
        if (gaps.size > windowSize) {                         // forget the oldest gap
            val old = gaps.removeFirst(); sum -= old; sumOfSquares -= old.toDouble() * old
        }
    }
    last = atMs
}

