fun phi(nowMs: Long): Double {
    val l = last ?: return 0.0
    if (gaps.isEmpty()) return 0.0
    val mean = gaps.average()
    val variance = gaps.sumOf { (it - mean) * (it - mean) } / gaps.size
    val stdDev = max(sqrt(variance), minStdDevMs)
    return -log10(probabilityLater((nowMs - l).toDouble(), mean, stdDev))
}
// phi 8 is about 5.6 standard deviations past the mean: 1,000 + 5.6 x 300, about 2,700 ms.
// A fixed 1,500 ms timeout is only 1.7 deviations past the mean: about 5% of gaps
// cross it, so with a heartbeat a second it raises a few false alarms a minute.
